/**
 * C9 grammar spotlight on a lesson page: the grammar note whose forms this lesson's own words or prayer lines contain
 * (data/grammar/spotlights.json, generated by tools/grammar/build-spotlights.mjs from the existing grammar data), its examples
 * from this lesson, and a three-question drill. Lessons with no matching form show nothing. Draft, unreviewed, and labelled so.
 */
import { el, heText } from '../curriculum/dom.js';
import { loadJSON } from '../curriculum/data.js';
import { displayHebrew } from '../shell/names.js';

const he = (s) => heText(displayHebrew(s, 'abbrev'), 'alef-he'); // the Name is never spelled out (ה׳)
/** The spotlight for a lesson, or null. */
export function spotlightFor(data, lessonId) {
  const l = data?.lessons?.[lessonId]; if (!l) return null;
  const t = data.topics?.[l.topic]; if (!t || !t.drill?.length) return null;
  return { topic: l.topic, title: t.title, summary: t.summary, examples: l.examples || [], drill: t.drill.slice(0, 3) };
}

/** A small drill: one question at a time, feedback with the data's own explanation, a score at the end. */
export function drillNode(drill) {
  const box = el('div', { class: 'alef-spot-drill' });
  let i = 0, right = 0;
  const show = () => {
    if (i >= drill.length) { box.replaceChildren(el('p', { role: 'status' }, `${right} of ${drill.length} right.`), el('button', { type: 'button', class: 'btn secondary', onclick: () => { i = 0; right = 0; show(); } }, 'Try the drill again')); return; }
    const q = drill[i], fb = el('p', { role: 'status', 'aria-live': 'polite' });
    let done = false;
    const opts = q.options.map((o, k) => el('button', { type: 'button', class: 'btn secondary', 'data-opt': String(k), lang: 'he', dir: 'rtl', onclick: () => {
      if (done) return; done = true; if (k === q.answer) right++;
      opts.forEach((b, j) => { b.disabled = true; b.setAttribute('disabled', ''); if (j === q.answer) b.setAttribute('data-state', 'right'); else if (j === k) b.setAttribute('data-state', 'wrong'); });
      fb.textContent = (k === q.answer ? 'Yes. ' : `Not this one. The answer is ${displayHebrew(q.options[q.answer], 'abbrev')}. `) + (q.explain ? displayHebrew(q.explain, 'abbrev') : '');
      next.hidden = false; next.removeAttribute('hidden'); next.focus?.();
    } }, displayHebrew(o, 'abbrev')));
    const next = el('button', { type: 'button', class: 'btn', hidden: '', onclick: () => { i++; show(); } }, i + 1 < drill.length ? 'Next question' : 'See the score');
    box.replaceChildren(el('p', {}, `Question ${i + 1} of ${drill.length}: ${displayHebrew(q.prompt, 'abbrev')}`), el('div', { class: 'row', role: 'group', 'aria-label': 'Choices' }, ...opts), fb, next);
  };
  show();
  return box;
}

/** The spotlight card (a closed details element, so it never pushes the lesson down). */
export function spotlightNode(s) {
  return el('details', { class: 'card alef-spotlight', 'data-topic': s.topic },
    el('summary', {}, el('strong', {}, `Grammar Spotlight: ${s.title}`)),
    el('p', {}, s.summary),
    s.examples.length ? el('ul', {}, ...s.examples.map((x) => el('li', {}, he(x.he), ' ', displayHebrew(x.note || x.meaning || '', 'abbrev'), x.label ? el('span', { class: 'muted' }, ` (${x.label})`) : null))) : null,
    el('p', { class: 'muted' }, 'Built by a program from the word list and the prayer library; no Hebrew teacher has checked it yet.'),
    drillNode(s.drill),
    el('p', {}, el('a', { href: `#/grammar/${s.topic}` }, 'The full grammar note')));
}

/** Fill `slot` with the lesson's spotlight (or leave it empty). */
export async function mountSpotlight(slot, lessonId, data) {
  const d = data || await loadJSON('data/grammar/spotlights.json');
  const s = spotlightFor(d, lessonId);
  slot.replaceChildren(...(s ? [spotlightNode(s)] : []));
  return s;
}
